arguments.new_str:
var builder = WebApplication.CreateBuilder(args);
builder.Services.AddScoped<IUserService, UserService>();
// Fix: Changed from Singleton to Scoped — a singleton capturing a scoped service
// violates scope validation (now enforced by default in development in .NET 9).
builder.Services.AddScoped<ICacheService>(sp =>
    new CacheService(sp.GetRequiredService<IUserService>()));
// Fix: Use ConfigurePrimaryHttpMessageHandler — the default primary handler is now
// SocketsHttpHandler in .NET 9, so casting to HttpClientHandler throws InvalidCastException.
builder.Services.AddHttpClient("api")
    .ConfigurePrimaryHttpMessageHandler(() => new HttpClientHandler { UseCookies = false });
// Fix: HttpClientFactory Trace-level logs now redact all header values by default.
// Allowlist the specific non-sensitive headers needed for debugging.
builder.Services.ConfigureHttpClientDefaults(b =>
    b.RedactLoggedHeaders(h =>
        h != "X-Request-Id" && h != "X-Correlation-Id" && h != "Cache-Control"));
builder.Services.Configure<ForwardedHeadersOptions>(options =>
{
    options.ForwardedHeaders = ForwardedHeaders.XForwardedFor;
    // Fix: In .NET 9, ForwardedHeadersMiddleware ignores X-Forwarded-* headers from
    // proxies not in KnownProxies/KnownNetworks. Clear the constraints for loopback
    // or add your trusted proxy addresses explicitly.
    options.KnownProxies.Clear();
    options.KnownNetworks.Clear();
});
var app = builder.Build();
app.UseForwardedHeaders();
app.Run();

